#include <cuda_fp16.h>

extern "C" __device__
void dx_cp_async_pair(
        float* first,
        float* second,
        const float* source,
        long long first_index,
        long long second_index) {
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        constexpr int fp32_ld = 36;
        constexpr int rows_per_load = 4;
        const int row = threadIdx.x / 32 + load * rows_per_load;
        const int col = threadIdx.x % 32;
        const int shared_index = row * fp32_ld + col;
        unsigned first_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(first + shared_index));
        unsigned second_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(second + shared_index));
        const float* first_global = source + first_index + load * 2048;
        const float* second_global = source + second_index + load * 2048;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 4;\n"
            :: "r"(first_shared), "l"(first_global));
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 4;\n"
            :: "r"(second_shared), "l"(second_global));
    }
    asm volatile("cp.async.commit_group;\n" ::);
}

extern "C" __device__
void dx_b1024_cp_async_fp32_tile(
        float* destination,
        const float* source,
        long long source_index,
        int global_ld) {
    // Let the final two warps stage the next 64x64 operand while the other six
    // warps enter the MathDx operation that consumes the current shared bank.
    if (threadIdx.x >= 192) {
        constexpr int shared_ld = 68;
        const int lane = threadIdx.x & 63;
        #pragma unroll
        for (int load = 0; load < 16; ++load) {
            const int chunk = lane + load * 64;
            const int row = chunk >> 4;
            const int col = (chunk & 15) << 2;
            const int shared_index = row * shared_ld + col;
            unsigned destination_shared = static_cast<unsigned>(
                __cvta_generic_to_shared(destination + shared_index));
            const float* source_global =
                source + source_index + row * global_ld + col;
            asm volatile(
                "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
                :: "r"(destination_shared), "l"(source_global));
            if ((load & 7) == 7) {
                asm volatile("cp.async.commit_group;\n" ::);
            }
        }
    }
}

extern "C" __device__
void dx_b1024_cp_async_half_tile(
        __half* destination,
        const __half* source,
        long long source_index,
        int global_ld) {
    constexpr int shared_ld = 72;
    #pragma unroll
    for (int load = 0; load < 2; ++load) {
        const int chunk = threadIdx.x + load * 256;
        const int row = chunk >> 3;
        const int col = (chunk & 7) << 3;
        unsigned destination_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(destination + row * shared_ld + col));
        const __half* source_global =
