}

extern "C" __device__
void dx_b1024_load_convert_half_tile(
        __half* destination,
        const float* source,
        long long source_index,
        int global_ld) {
    constexpr int shared_ld = 72;
    const int row = threadIdx.x >> 4;
    const int col = (threadIdx.x & 15) << 2;
    #pragma unroll
    for (int load = 0; load < 4; ++load) {
        const int current_row = row + load * 16;
        const float4 values = *reinterpret_cast<const float4*>(
            source + source_index + current_row * global_ld + col);
        __half2* packed = reinterpret_cast<__half2*>(
