        packed[0] = __floats2half2_rn(values.x, values.y);
        packed[1] = __floats2half2_rn(values.z, values.w);
    }
}

extern "C" __device__
void dx_copy_float8(
        float* destination,
        const float* source,
        long long index) {
    float4* destination_vectors = reinterpret_cast<float4*>(
        destination + index);
    const float4* source_vectors = reinterpret_cast<const float4*>(
        source + index);
    destination_vectors[0] = source_vectors[0];
    destination_vectors[1] = source_vectors[1];
}

extern "C" __device__
void g2048_store_upper_zero_lower(
        const float* source,
        float* destination,
        long long destination_index,
        long long leading) {
    const int row = threadIdx.x >> 3;
    const int col = (threadIdx.x & 7) << 2;
    float4 values = *reinterpret_cast<const float4*>(
        source + row * 32 + col);
    if (row > col) values.x = 0.0f;
    if (row > col + 1) values.y = 0.0f;
    if (row > col + 2) values.z = 0.0f;
    if (row > col + 3) values.w = 0.0f;
    *reinterpret_cast<float4*>(
        destination + destination_index + row * leading + col) = values;
}

extern "C" __device__
void g2048_store_panel_float4(
        const float* source,
        float* destination,
        long long destination_index,
        long long symmetric_index,
        long long leading,
        int clear_symmetric) {
    if (threadIdx.x < 128) {
        const int row = threadIdx.x >> 2;
