extern "C" __device__
void d256_store_fp32_tile(
        const float* source,
        float* output,
        long long output_index) {
    constexpr int source_ld = 68;
    constexpr int output_ld = 256;
    const int row = threadIdx.x >> 4;
    const int col = (threadIdx.x & 15) * 4;
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        const int current_row = row + load * 8;
        const float4 values = *reinterpret_cast<const float4*>(
            source + current_row * source_ld + col);
        *reinterpret_cast<float4*>(
            output + output_index + current_row * output_ld + col) = values;
    }
}

extern "C" __device__
void d256_store_fp32_upper_tile(
        const float* source,
        float* output,
        long long output_index) {
    constexpr int source_ld = 68;
    constexpr int output_ld = 256;
    const int row = threadIdx.x >> 4;
    const int col = (threadIdx.x & 15) * 4;
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        const int current_row = row + load * 8;
        const float4 values = *reinterpret_cast<const float4*>(
            source + current_row * source_ld + col);
        float* destination =
            output + output_index + current_row * output_ld + col;
        if (current_row <= col) {
            *reinterpret_cast<float4*>(destination) = values;
        } else if (current_row <= col + 3) {
            if (current_row <= col + 1) destination[1] = values.y;
            if (current_row <= col + 2) destination[2] = values.z;
            destination[3] = values.w;
        }
    }
}

extern "C" __device__
void d256_store_fp32_and_shared_half_prefetch(
        float* source,
        float* output,
        __half* destination,
        const float* accumulator_source,
        long long output_index,
        long long accumulator_index) {
    constexpr int source_ld = 68;
    constexpr int output_ld = 256;
    constexpr int destination_ld = 72;
    const int row = threadIdx.x >> 4;
    const int col = (threadIdx.x & 15) * 4;
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        const int current_row = row + load * 8;
        const float4 values = *reinterpret_cast<const float4*>(
            source + current_row * source_ld + col);
        *reinterpret_cast<float4*>(
            output + output_index + current_row * output_ld + col) = values;
        __half2* packed = reinterpret_cast<__half2*>(
            destination + current_row * destination_ld + col);
        packed[0] = __floats2half2_rn(values.x, values.y);
        packed[1] = __floats2half2_rn(values.z, values.w);
        unsigned accumulator_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(
                source + current_row * source_ld + col));
        const float* accumulator_global =
            accumulator_source
            + accumulator_index
            + current_row * output_ld
            + col;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
            :: "r"(accumulator_shared), "l"(accumulator_global)
            : "memory");
    }
    asm volatile("cp.async.commit_group;\n" ::);
}

extern "C" __device__
void dx_async_bulk_init(unsigned long long* barriers) {
    if (threadIdx.x == 0) {
        unsigned barrier_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(barriers));
        asm volatile(
            "mbarrier.init.shared::cta.b64 [%0], 1;\n"
            :: "r"(barrier_shared) : "memory");
    }
    __syncthreads();
}

extern "C" __device__
void dx_async_bulk_wait(
        unsigned long long* barriers,
        int phase) {
    if (threadIdx.x == 0) {
        unsigned barrier_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(barriers));
        asm volatile(
            "{\n"
            ".reg .pred ready;\n"
            "DX_BULK_WAIT:\n"
            "mbarrier.try_wait.parity.shared::cta.b64 ready, [%0], %1;\n"
            "@ready bra DX_BULK_DONE;\n"
            "bra DX_BULK_WAIT;\n"
            "DX_BULK_DONE:\n"
            "}\n"
            :: "r"(barrier_shared), "r"(phase) : "memory");
    }
    __syncthreads();
}

extern "C" __device__
void dx_cp_async_wait() {
    asm volatile("cp.async.wait_group 0;\n" ::);
}
