void grouped_prepare_(
        torch::Tensor input,
        torch::Tensor output,
        torch::Tensor flags) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(input.scalar_type() == at::kFloat &&
                output.scalar_type() == at::kFloat, "FP32 tensors required");
    TORCH_CHECK(input.is_contiguous() && output.is_contiguous() &&
                input.sizes() == output.sizes(), "invalid matrix buffers");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
                "square matrix batches required");
    TORCH_CHECK(flags.is_cuda() && flags.scalar_type() == at::kInt,
                "CUDA int32 flags required");
    grouped_upper_copy_cuda(input, output, flags);
}

void grouped_panel_update_(
        torch::Tensor output,
        torch::Tensor pointers,
        int64_t block_size,
        int64_t panel_index_value) {
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat &&
                output.is_contiguous(), "contiguous CUDA FP32 output required");
    TORCH_CHECK(output.dim() == 3 && output.size(1) == output.size(2),
                "square matrix batches required");
    const int batch = static_cast<int>(output.size(0));
    const int n = static_cast<int>(output.size(1));
    const int block = static_cast<int>(block_size);
